// Some portions generated by Claude
export class QueryFailure extends Error {
  status: number;
  retryAfterMs: number;
  constructor(message: string, status = 0, retryAfterMs = 0) {
    super(message);
    this.status = status;
    this.retryAfterMs = retryAfterMs;
  }
}
export type BatchReply<T> = {
  values: Map<string, T>;
  rows?: number;
  saturated?: boolean;
};
type Pending<T> = {
  promise: Promise<T | undefined>;
  resolve: (v: T | undefined) => void;
  reject: (e: unknown) => void;
  users: Set<symbol>;
};
const abortError = () => new DOMException("Request cancelled", "AbortError");

/** Endpoint/template-local accumulation. One cancellation never cancels another consumer. */
export class AdaptiveBatchLoader<T> {
  private pending = new Map<string, Pending<T>>();
  private queued = new Set<string>();
  private timer: ReturnType<typeof setTimeout> | undefined;
  private active:
    | { entries: Map<string, Pending<T>>; controller: AbortController }
    | undefined;
  private lastLoad = -Infinity;
  private windowStarted = 0;
  private disposed = false;
  readonly stats = {
    requests: 0,
    keys: 0,
    deduplicated: 0,
    splits: 0,
    batchSize: 32,
    delayMs: 80,
  };
  private fetchBatch: (
    keys: string[],
    signal: AbortSignal,
  ) => Promise<BatchReply<T>>;
  private options: {
    initialSize?: number;
    maximumSize?: number;
    windowMs?: number;
  };
  constructor(
    fetchBatch: (keys: string[], signal: AbortSignal) => Promise<BatchReply<T>>,
    options: {
      initialSize?: number;
      maximumSize?: number;
      windowMs?: number;
    } = {},
  ) {
    this.fetchBatch = fetchBatch;
    this.options = options;
    this.stats.batchSize = options.initialSize ?? 32;
  }
  load(key: string, signal?: AbortSignal): Promise<T | undefined> {
    if (this.disposed || signal?.aborted) return Promise.reject(abortError());
    let entry = this.pending.get(key);
    if (
      this.active?.controller.signal.aborted &&
      this.active.entries.get(key) === entry
    )
      entry = undefined;
    if (!entry) {
      let resolve!: Pending<T>["resolve"], reject!: Pending<T>["reject"];
      const promise = new Promise<T | undefined>((yes, no) => {
        resolve = yes;
        reject = no;
      });
      void promise.catch(() => {});
      entry = { promise, resolve, reject, users: new Set() };
      this.pending.set(key, entry);
      this.queued.add(key);
    } else this.stats.deduplicated++;
    const user = Symbol();
    entry.users.add(user);
    const now = performance.now();
    this.stats.delayMs =
      this.options.windowMs ?? (now - this.lastLoad < 450 ? 220 : 80);
    this.lastLoad = now;
    if (this.timer && this.options.windowMs === undefined) {
      clearTimeout(this.timer);
      this.timer = undefined;
      this.schedule(
        Math.max(
          0,
          Math.min(this.stats.delayMs, 350 - (now - this.windowStarted)),
        ),
      );
    } else {
      if (!this.active && !this.timer) this.windowStarted = now;
      this.schedule();
    }
    const captured = entry;
    return new Promise((resolve, reject) => {
      const cleanup = () => {
        signal?.removeEventListener("abort", cancel);
        captured.users.delete(user);
      };
      const cancel = () => {
        cleanup();
        reject(abortError());
        if (!captured.users.size && this.queued.delete(key)) {
          this.pending.delete(key);
          captured.reject(abortError());
        }
        if (
          this.active &&
          [...this.active.entries.values()].every((item) => !item.users.size)
        )
          this.active.controller.abort();
      };
      signal?.addEventListener("abort", cancel, { once: true });
      captured.promise.then(
        (value) => {
          cleanup();
          resolve(value);
        },
        (error) => {
          cleanup();
          reject(error);
        },
      );
    });
  }
  get idle() {
    return !this.pending.size && !this.active;
  }
  loadMany(keys: string[], signal?: AbortSignal) {
    return Promise.all(
      [...new Set(keys)].map(
        async (key) => [key, await this.load(key, signal)] as const,
      ),
    );
  }
  private schedule(delay = this.stats.delayMs) {
    if (this.active || this.timer || !this.queued.size || this.disposed) return;
    this.timer = setTimeout(() => {
      this.timer = undefined;
      void this.flush();
    }, delay);
  }
  private async request(
    keys: string[],
    signal: AbortSignal,
    retry = 0,
  ): Promise<Map<string, T>> {
    if (signal.aborted) throw abortError();
    const started = performance.now();
    this.stats.requests++;
    this.stats.keys += keys.length;
    let split = false;
    try {
      const reply = await this.fetchBatch(keys, signal);
      const ms = performance.now() - started;
      if (reply.saturated && keys.length > 1) split = true;
      else {
        if (ms > 1800 || (reply.rows ?? 0) > keys.length * 64)
          this.stats.batchSize = Math.max(
            1,
            Math.floor(this.stats.batchSize / 2),
          );
        else if (ms < 600 && !reply.saturated)
          this.stats.batchSize = Math.min(
            this.options.maximumSize ?? 128,
            this.stats.batchSize + 4,
          );
        return reply.values;
      }
    } catch (error) {
      if (signal.aborted) throw abortError();
      const transient =
        error instanceof QueryFailure &&
        [408, 413, 414, 429, 502, 503, 504].includes(error.status);
      if (!transient) throw error;
      this.stats.batchSize = Math.max(1, Math.floor(this.stats.batchSize / 2));
      if ([429, 503].includes(error.status))
        await abortableDelay(
          Math.min(30000, Math.max(200, error.retryAfterMs)),
          signal,
        );
      if (keys.length > 1) split = true;
      else if (retry < 2) return this.request(keys, signal, retry + 1);
      else throw error;
    }
    if (split) {
      this.stats.splits++;
      this.stats.batchSize = Math.max(1, Math.floor(this.stats.batchSize / 2));
      const half = Math.ceil(keys.length / 2);
      const left = await this.request(keys.slice(0, half), signal);
      const right = await this.request(keys.slice(half), signal);
      return new Map([...left, ...right]);
    }
    return new Map();
  }
  private async flush() {
    if (this.active || this.disposed) return;
    const keys = [...this.queued].slice(0, this.stats.batchSize);
    if (!keys.length) return;
    keys.forEach((k) => this.queued.delete(k));
    const controller = new AbortController();
    const entries = new Map(keys.map((key) => [key, this.pending.get(key)!]));
    this.active = { entries, controller };
    const settle = (key: string, value: T | undefined, error?: unknown) => {
      const entry = entries.get(key)!;
      if (error) entry.reject(error);
      else entry.resolve(value);
      if (this.pending.get(key) === entry) this.pending.delete(key);
    };
    try {
      const values = await this.request(keys, controller.signal);
      keys.forEach((k) => settle(k, values.get(k)));
    } catch (error) {
      keys.forEach((k) => settle(k, undefined, error));
    } finally {
      this.active = undefined;
      this.schedule(0);
    }
  }
  dispose() {
    this.disposed = true;
    clearTimeout(this.timer);
    this.active?.controller.abort();
    for (const entry of this.pending.values()) entry.reject(abortError());
    this.pending.clear();
    this.queued.clear();
  }
}

export function abortableDelay(ms: number, signal: AbortSignal) {
  return new Promise<void>((resolve, reject) => {
    if (signal.aborted) {
      reject(abortError());
      return;
    }
    const cancel = () => {
      clearTimeout(timer);
      reject(abortError());
    };
    const timer = setTimeout(() => {
      signal.removeEventListener("abort", cancel);
      resolve();
    }, ms);
    signal.addEventListener("abort", cancel, { once: true });
  });
}

/** The UTF-8 length of a string, as TextEncoder would encode it (a lone surrogate becomes U+FFFD), without encoding it. */
export function utf8Length(text: string) {
  let bytes = 0;
  for (let index = 0; index < text.length; index++) {
    const code = text.charCodeAt(index);
    if (code < 0x80) bytes += 1;
    else if (code < 0x800) bytes += 2;
    else if (code >= 0xd800 && code <= 0xdbff && (text.charCodeAt(index + 1) & 0xfc00) === 0xdc00) {
      bytes += 4;
      index++;
    } else bytes += 3;
  }
  return bytes;
}

/** Byte-bounded LRU; expiration is checked on every read, including negative results. */
export class BoundedCache<T> {
  private entries = new Map<
    string,
    { value: T; expires: number; bytes: number }
  >();
  private bytes = 0;
  private maxEntries: number;
  private maxBytes: number;
  private now: () => number;
  constructor(maxEntries = 4096, maxBytes = 2_000_000, now = () => Date.now()) {
    this.maxEntries = maxEntries;
    this.maxBytes = maxBytes;
    this.now = now;
  }
  get(key: string): T | undefined {
    const item = this.entries.get(key);
    if (!item) return;
    if (item.expires <= this.now()) {
      this.delete(key);
      return;
    }
    this.entries.delete(key);
    this.entries.set(key, item);
    return item.value;
  }
  /**
   * Stores `value` for `ttlMs`. Its size is that of `JSON.stringify([key, value])` in UTF-8; a caller that stores the
   * same value in several caches passes `valueJson` (JSON.stringify(value)) so it is serialized once.
   */
  set(key: string, value: T, ttlMs: number, valueJson = JSON.stringify(value)) {
    this.delete(key);
    // "[" key "," value "]", measured without building the string or its bytes.
    const bytes = utf8Length(JSON.stringify(key)) + utf8Length(valueJson ?? "null") + 3;
    if (bytes > this.maxBytes || ttlMs <= 0) return;
    this.entries.set(key, { value, bytes, expires: this.now() + ttlMs });
    this.bytes += bytes;
    while (this.entries.size > this.maxEntries || this.bytes > this.maxBytes)
      this.delete(this.entries.keys().next().value!);
  }
  delete(key: string) {
    const old = this.entries.get(key);
    if (old) this.bytes -= old.bytes;
    this.entries.delete(key);
  }
  clear() {
    this.entries.clear();
    this.bytes = 0;
  }
  snapshot() {
    return [...this.entries]
      .filter(([, item]) => item.expires > this.now())
      .map(([key, item]) => [key, item.value, item.expires] as const);
  }
  restore(rows: unknown, validate: (value: unknown) => value is T) {
    if (!Array.isArray(rows)) return;
    for (const row of rows.slice(-this.maxEntries))
      if (
        Array.isArray(row) &&
        typeof row[0] === "string" &&
        row[0].length <= 8192 &&
        typeof row[2] === "number" &&
        Number.isFinite(row[2]) &&
        validate(row[1])
      )
        this.set(row[0], row[1], Math.min(86400000, row[2] - this.now()));
  }
}

/** Fair per-endpoint concurrency cap shared by metadata and expansion templates. */
export class QueryScheduler {
  private running = 0;
  private waiting: { start: () => void; cancel: () => void }[] = [];
  private maximum: number;
  constructor(maximum = 3) {
    this.maximum = maximum;
  }
  async run<T>(operation: () => Promise<T>, signal?: AbortSignal): Promise<T> {
    if (signal?.aborted) throw abortError();
    await new Promise<void>((resolve, reject) => {
      const item = {
        start: () => {
          signal?.removeEventListener("abort", item.cancel);
          this.running++;
          resolve();
        },
        cancel: () => {
          this.waiting = this.waiting.filter((other) => other !== item);
          reject(abortError());
        },
      };
      if (this.running < this.maximum) item.start();
      else {
        this.waiting.push(item);
        signal?.addEventListener("abort", item.cancel, { once: true });
      }
    });
    try {
      if (signal?.aborted) throw abortError();
      return await operation();
    } finally {
      this.running--;
      this.waiting.shift()?.start();
    }
  }
}
